/**
 * Initialize the activity filter.
 *
 * @param {Array} hiddenModules Array of module names to hide
 */
export const init = (hiddenModules) => {
    // If no hidden modules, nothing to do.
    if (!hiddenModules || hiddenModules.length === 0) {
        return;
    }

    // Function to hide activities.
    const hideActivities = () => {
        hiddenModules.forEach(moduleName => {
            // Find all activity options with this module name.
            const selector = `[data-region="chooser-option-container"][data-internal="${moduleName}"]`;
            const options = document.querySelectorAll(selector);

            options.forEach(option => {
                // Hide the option.
                option.style.display = 'none';
                // Also mark it as hidden for accessibility.
                option.setAttribute('aria-hidden', 'true');
            });
        });

        // After hiding, check if any tab content is empty and hide empty categories.
        checkEmptyCategories();
    };

    // Function to check and handle empty categories.
    const checkEmptyCategories = () => {
        // Find all tab panes.
        const tabPanes = document.querySelectorAll('[data-region="tabcontent"] .tab-pane');

        tabPanes.forEach(pane => {
            const optionsContainer = pane.querySelector('[data-region="chooser-options-container"]');
            if (!optionsContainer) {
                return;
            }

            // Count visible options.
            const visibleOptions = optionsContainer.querySelectorAll(
                '[data-region="chooser-option-container"]:not([style*="display: none"])'
            );

            // If no visible options, you could optionally hide the entire tab.
            // For now, we'll just let it show empty.
        });
    };

    // Wait for the modal to be shown, then hide activities.
    // The modal might already be in the DOM or might be created dynamically.
    const observer = new MutationObserver((mutations) => {
        mutations.forEach((mutation) => {
            mutation.addedNodes.forEach((node) => {
                if (node.nodeType === 1) { // Element node.
                    // Check if this is the modal or contains the modal.
                    if (node.matches && node.matches('.modal[data-region="modal-container"]')) {
                        hideActivities();
                    } else if (node.querySelector) {
                        const modal = node.querySelector('.modal[data-region="modal-container"]');
                        if (modal) {
                            hideActivities();
                        }
                    }
                }
            });
        });
    });

    // Observe the body for modal additions.
    observer.observe(document.body, {
        childList: true,
        subtree: true,
    });

    // Also check if modal is already present.
    if (document.querySelector('.modal[data-region="modal-container"]')) {
        hideActivities();
    }
};
